	array(
		'question_text' => 'A private clinic offers an APCC a 1099 independent-contractor position. Clients would pay the APCC directly, the APCC would rent an office from the clinic, and a licensed clinician would be available for optional consultation. What is the BEST response?',
		'option_a' => 'Accept because a 1099 classification is allowed if supervision is available.',
