	array(
		'question_text' => 'An LPCC is asked to administer an individually administered intelligence test to answer a school-placement question. The LPCC is otherwise experienced with counseling assessments. What is the BEST response?',
		'option_a' => 'Administer it after reading the manual because competence is the only issue.',
		'option_b' => 'Decline the excluded testing activity and refer to an appropriately qualified professional rather than treating general assessment experience as authority for the test.',
