	array(
		'question_text' => 'A current client tells an LPCC that the client wants to begin a consensual sexual relationship with the counselor outside the office. Which response is most accurate?',
		'option_a' => 'The relationship is allowed if the client initiates it.',
		'option_b' => 'The relationship is allowed if treatment is paused for one week.',
		'option_c' => 'The LPCC must maintain the professional boundary; client consent and an off-site setting do not make sexual conduct with a current client permissible.',
